import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = [row for row in reader if row]

    header_index = None
    for index, row in enumerate(records):
        if len(row) >= 2:
            first = row[0].lstrip("\ufeff").strip().casefold()
            second = row[1].strip().casefold()
            if first == "id" and second == "text":
                header_index = index
                break

    if header_index is None:
        header_index = 0

    columns = list(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    width = len(columns)
    rows = []

    for record in records[header_index + 1:]:
        row = list(record)

        if width >= 3 and len(row) > width:
            extra = len(row) - width
            row = row[:1] + [",".join(row[1:2 + extra])] + row[2 + extra:]

        if len(row) < width:
            row.extend([""] * (width - len(row)))

        rows.append(row)

    return {"columns": columns, "rows": rows}
